#include <iostream>
#include <string>
#include <algorithm>
#include <random>
#include <cmath>
#include <ctime>
#include <chrono>
#include <iomanip>
#include <sstream>

using namespace std;

const int MODEL_SIZE = 26 * 26 * 26 * 26;
const int STEPS = 30000;
const int DEFAULT_RESTARTS = 60;
float englishScore[MODEL_SIZE];
extern const char* const ENGLISH_MODEL[];

struct Result {
    string key;
    double score;
    unsigned long long evaluations;
    int restarts;
};

int letterIndex(char c) {
    if (c >= 'A' && c <= 'Z') return c - 'A';
    if (c >= 'a' && c <= 'z') return c - 'a';
    return -1;
}

string normalize(const string& text) {
    string result;
    for (size_t i = 0; i < text.size(); ++i) {
        int letter = letterIndex(text[i]);
        if (letter >= 0) result += static_cast<char>('A' + letter);
    }
    return result;
}
bool loadEnglishModel() {
    const string alphabet = "!#$%&'()*+,-./0123456789:;<=>@ABCDEFGHIJKLMNOPQRSTUVWXYZ[]^_`abcdefghijklmnopqrstuvwxyz{|}~";
    int lookup[128];
    fill(lookup, lookup + 128, -1);
    for (size_t i = 0; i < alphabet.size(); ++i)
        lookup[static_cast<unsigned char>(alphabet[i])] = static_cast<int>(i);
    int position = 0;
    for (int block = 0; ENGLISH_MODEL[block] != NULL; ++block) {
        for (const char* p = ENGLISH_MODEL[block]; *p != '\0'; ++p) {
            unsigned char code = static_cast<unsigned char>(*p);
            if (position >= MODEL_SIZE || code >= 128 || lookup[code] < 0) return false;
            englishScore[position++] = static_cast<float>(-11.625737130222220 + 0.101328135395403 * lookup[code]);
        }
    }
    return position == MODEL_SIZE;
}

string initialKey(const string& cipher) {
    int count[26] = {};
    int order[26];
    for (size_t i = 0; i < cipher.size(); ++i) ++count[cipher[i] - 'A'];
    for (int i = 0; i < 26; ++i) order[i] = i;
    stable_sort(order, order + 26, [&](int a, int b) { return count[a] > count[b]; });
    const string frequency = "ETAOINSHRDLCUMWFGYPBVKJXQZ";
    string key(26, ' ');
    for (int i = 0; i < 26; ++i) key[order[i]] = frequency[i];
    return key;
}
double scoreKey(const string& cipher, const string& key) {
    int code = 0;
    double score = 0;
    for (size_t i = 0; i < cipher.size(); ++i) {
        code = (code % (26 * 26 * 26)) * 26 + key[cipher[i] - 'A'] - 'A';
        if (i >= 3) score += englishScore[code];
    }
    return 300.0 * score / static_cast<double>(cipher.size() - 3);
}

string decode(const string& original, const string& key) {
    string result = original;
    for (size_t i = 0; i < result.size(); ++i) {
        int letter = letterIndex(result[i]);
        if (letter >= 0) result[i] = key[letter];
    }
    return result;
}

double indexOfCoincidence(const string& cipher) {
    double count[26] = {};
    for (size_t i = 0; i < cipher.size(); ++i) ++count[cipher[i] - 'A'];
    double sum = 0;
    for (int i = 0; i < 26; ++i) sum += count[i] * (count[i] - 1);
    double length = static_cast<double>(cipher.size());
    return sum / (length * (length - 1));
}
void hillClimb(const string& cipher, string& key, double& score, Result& result) {
    while (true) {
        int bestA = -1, bestB = -1;
        double bestScore = score;
        for (int a = 0; a < 25; ++a) {
            for (int b = a + 1; b < 26; ++b) {
                swap(key[a], key[b]);
                double candidate = scoreKey(cipher, key);
                ++result.evaluations;
                swap(key[a], key[b]);
                if (candidate > bestScore + 1e-9) {
                    bestScore = candidate;
                    bestA = a;
                    bestB = b;
                }
            }
        }
        if (bestA == -1) return;
        swap(key[bestA], key[bestB]);
        score = bestScore;
    }
}

void search(const string& cipher, int restarts, Result& result, mt19937& random) {
    uniform_int_distribution<int> letter(0, 25);
    uniform_real_distribution<double> probability(0.0, 1.0);
    const string frequencyKey = initialKey(cipher);
    const double cooling = pow(0.08 / 12.0, 1.0 / (STEPS - 1));
    for (int run = 0; run < restarts; ++run) {
        int number = result.restarts;
        string key = number % 3 == 2 ? result.key : frequencyKey;
        if (number % 3 == 1) {
            shuffle(key.begin(), key.end(), random);
        }
        else if (number > 0) {
            for (int i = 0; i < 8; ++i) {
                int a = letter(random), b = letter(random);
                swap(key[a], key[b]);
            }
        }
        double currentScore = scoreKey(cipher, key);
        ++result.evaluations;
        string bestKey = key;
        double bestScore = currentScore;
        double temperature = 12.0;
        for (int step = 0; step < STEPS; ++step) {
            int a = letter(random), b = letter(random);
            while (a == b) b = letter(random);
            swap(key[a], key[b]);
            double candidate = scoreKey(cipher, key);
            ++result.evaluations;
            double change = candidate - currentScore;
            if (change >= 0 || probability(random) < exp(change / temperature)) {
                currentScore = candidate;
                if (currentScore > bestScore) {
                    bestScore = currentScore;
                    bestKey = key;
                }
            }
            else {
                swap(key[a], key[b]);
            }
            temperature *= cooling;
        }
        hillClimb(cipher, bestKey, bestScore, result);
        if (bestScore > result.score) {
            result.key = bestKey;
            result.score = bestScore;
        }
        ++result.restarts;
        if ((run + 1) % 5 == 0 || run + 1 == restarts)
            cout << "Da tim " << run + 1 << "/" << restarts
            << " | Diem tot nhat: " << fixed << setprecision(3) << result.score << '\n';
    }
}

int readRestarts() {
    string line;
    while (true) {
        cout << "So lan tim lai [Enter = " << DEFAULT_RESTARTS << "]: ";
        if (!getline(cin, line)) return 0;
        if (line.empty() || line == "\r") return DEFAULT_RESTARTS;
        istringstream input(line);
        int value;
        char extra;
        if ((input >> value) && !(input >> extra) && value >= 1 && value <= 10000) return value;
        cout << "Hay nhap so nguyen tu 1 den 10000.\n";
    }
}

int main() {
    cout << "GIAI MA MONO-ALPHABETIC SUBSTITUTION\n";
    cout << "Nhap ciphertext. Ket thuc bang mot dong trong:\n";
    string original, line;
    while (getline(cin, line)) {
        if (!line.empty() && line[line.size() - 1] == '\r') line.erase(line.size() - 1);
        if (line.empty()) break;
        if (!original.empty()) original += '\n';
        original += line;
    }
    string cipher = normalize(original);
    if (cipher.size() < 4) {
        cout << "Can it nhat 4 chu cai A-Z. Nen dung vai tram chu cai de de giai dung.\n";
        return 1;
    }
    if (!loadEnglishModel()) {
        cout << "Du lieu thong ke trong ma nguon bi thieu hoac bi sua.\n";
        return 1;
    }
    if (cipher.size() < 100) cout << "Luu y: ban ma ngan, ket qua co the khong chinh xac.\n";
    unsigned int seed = static_cast<unsigned int>(time(NULL));
    mt19937 random(seed);
    Result result;
    result.key = initialKey(cipher);
    result.score = scoreKey(cipher, result.key);
    result.evaluations = 1;
    result.restarts = 0;
    double totalSeconds = 0;
    cout << "So chu cai: " << cipher.size() << " | IC: " << fixed << setprecision(6)
        << indexOfCoincidence(cipher) << " | Seed: " << seed << '\n';
    while (true) {
        int restarts = readRestarts();
        if (restarts == 0) break;
        chrono::steady_clock::time_point start = chrono::steady_clock::now();
        search(cipher, restarts, result, random);
        totalSeconds += chrono::duration<double>(chrono::steady_clock::now() - start).count();
        cout << "\nBAN RO TOT NHAT:\n" << decode(original, result.key) << '\n';
        cout << "\nDiem: " << fixed << setprecision(6) << result.score
            << "\nTong so lan tim lai: " << result.restarts
            << "\nSo lan danh gia: " << result.evaluations
            << "\nThoi gian tim kiem: " << setprecision(3) << totalSeconds << " giay\n";
        cout << "Diem cang lon cang tot; khong phai phan tram chinh xac.\n";
        cout << "\nTim tiep de cai thien? (y/n): ";
        if (!getline(cin, line) || (line != "y" && line != "Y" && line != "y\r" && line != "Y\r")) break;
    }
    return 0;
}
